#include <iostream>
using namespace std;

int main() {
    const int MAX = 50;
    double notas[MAX] = {};
    int n;
    cout << "Quantos alunos (até 50)? ";
    cin >> n;
    if (n < 1 || n > MAX) {
        cout << "Quantidade inválida." << endl;
        return 0;
    }
    double soma = 0;
    for (int i = 0; i < n; i++) {
        cout << "Nota " << i + 1 << ": ";
        cin >> notas[i];
        soma += notas[i];
    }
    double media = soma / n;
    cout << "Média: " << media << endl;
    cout << "Acima da média:";
    for (int i = 0; i < n; i++) {
        if (notas[i] > media) cout << " " << notas[i];
    }
    cout << endl;
    return 0;
}
// 4 alunos com 7, 4.5, 9 e 6 -> Média: 6.625
// Acima da média: 7 9

