#include <iostream>
#include <string>
using namespace std;

int main() {
    int votos[6] = {};        // usa 1 a 5; a posição 0 sobra
    int voto;
    cout << "Notas de 1 a 5 (0 para terminar): ";
    while (cin >> voto && voto != 0) {
        if (voto >= 1 && voto <= 5) {
            votos[voto]++;    // o voto é o índice
        }
    }
    for (int k = 1; k <= 5; k++) {
        cout << k << ": " << string(votos[k], '*')
             << " (" << votos[k] << ")" << endl;
    }
    return 0;
}

